preConditionHook:
// BODY MA BAND BREAKOUT (Brian's notes P2): SMA of body tops and of body
// bottoms over bandLength; long when close > midpoint + bandMultiple x width,
// short mirrored. EL: Average of MaxList / MinList of the open and close,
// fresh loops over PRICE expressions with real history (not a mirrored
// variable buffer), summed newest-first and divided by the (int) bound, the
// AvgBodyBelowRangeFraction form. Scratch reset before the loop.
bodyTopAvg = 0.0;
bodyBottomAvg = 0.0;
for (int i = 0; i < (int)bandLength; ++i) {
    bodyTopAvg += open[i] > close[i] ? open[i] : close[i];
    bodyBottomAvg += open[i] < close[i] ? open[i] : close[i];
}
bodyTopAvg /= (int)bandLength;
bodyBottomAvg /= (int)bandLength;
bandMid = (bodyTopAvg + bodyBottomAvg) / 2;
bodyBandWidth = bodyTopAvg - bodyBottomAvg;
